impl BlockSimulator {
    fn new() -> Self {
        // 19: 11111 <E 101
        // 19: L P N N <E K R1
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L, P, Run(N, 2)],
            right_tape: vec![R1, Run(K, 1)],
            state: HigherState::LeftE,
            base_steps: 19,
            self_steps: 0,
        }
    }

    fn step(&mut self) -> Result<(), SimError> {
        use BlockSymbol::*;
        use HigherState::*;
        use RunSymbolType::*;

        if self.state == RightC {
            if matches!(self.right_tape.as_slice(), [R1, Q]) {
                // c> Q R1 -> 10 D> 1$ ***HALT***
                self.base_steps += 1;
                self.self_steps += 1;
                return Err(SimError::Halted);
            } else if matches!(self.right_tape.as_slice(), [.., Run(K, 1..), Q]) {
                // c> Q K -> 10 D> 10 ***HALT***
                self.base_steps += 1;
                self.self_steps += 1;
                return Err(SimError::Halted);
            }
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps += new_base_steps;
        self.self_steps += 1;
        Ok(())
    }

    fn run_to_next_config(&mut self) -> Option<AConfig> {
        loop {
            // println!("{self}");
            match self.step() {
                Err(SimError::Halted) => return None,
                Err(e) => panic!("{e}"),
                _ => (),
            }
            if let Some(c) = self.parse_A_config() {
                // println!("{self}");
                return Some(c);
            }
        }
    }

    /// A(a,b) = 0^inf 1^a A> 1 1^b 01 0^inf
    fn parse_A_config(&self) -> Option<AConfig> {
        use BlockSymbol::*;
        use RunSymbolType::*;
        if self.state != HigherState::RightA || self.right_tape.first() != Some(&R1) {
            return None;
        }
        let mut left_a = 0;
        assert!(self.left_tape[0] == L);
        for s in &self.left_tape[1..] {
            match s {
                Run(N, x) => left_a += x * 2,
                P => left_a += 1,
                _ => return None,
            }
        }
        let mut right_exp = 0;
        match self.right_tape.get(1) {
            Some(Run(K, 1)) => right_exp += 1,
            Some(Q) => (),
            _ => return None,
        }
        for s in &self.right_tape[2..] {
            match s {
                Run(N, x) => right_exp += x * 2,
                P => right_exp += 1,
                _ => return None,
            }
        }
        if right_exp == 0 {
            return None;
        }
        Some(AConfig {
            a: left_a,
            b: right_exp - 1,
        })
    }
}

