fn sim_a_config() {
    let mut config = AConfig { a: 6, b: 1 };
    println!("{config}");
    for k in 1..=1_000_000_000_000_0u64 {
        if let Some(c) = config.next() {
            config = c;
            if config.a % 4 == 2 && config.a * 2 + 18 == config.b {
                println!("{config} nonhalting");
                break;
            }
            if k % 1_000_000_000 == 0 || config.a == 2396758 {
                println!("{k}: {config}");
            }
        } else {
            println!("{config} halted");
            break;
        }
    }
}

fn check_g_config_rules() {
    for c in 0..300 {
        for b in 0..300 {
            let g = GConfig { c, b };
            let (next, rule) = g.next();
            let next2 = g.to_A_config().to_sim().run_to_next_config();
            if let Some(g_next) = next {
                assert!(next2.is_some());
                assert!(g_next.to_A_config() == next2.unwrap());
            } else {
                assert!(next2.is_none());
            }
        }
    }
}

fn run_to_next_main_config(config0: GConfig, print: bool) -> u32 {
    let mut config = config0;
    let limit = (config.c + config.b + 1).ilog2() * 50;
    let mut n_steps = 0;
    let mut reached_next = false;
    while n_steps < limit {
        let (res, _) = config.next();
        n_steps += 1;
        match res {
            Some(g @ GConfig { c: 0 | 8, b: _ }) => {
                config = g;
                reached_next = true;
                break;
            }
            Some(g) => {
                config = g;
            }
            None => {
                reached_next = true;
                break;
            }
        }
    }
    if reached_next {
        if print {
            println!("{config0} -> {config}, {n_steps} steps");
        }
        n_steps
    } else {
        if print {
            println!("{config0} timed out");
        }
        0
    }
}

use npyz::{TypeStr, WriterBuilder};
use std::{fs, io};
fn write_array_1d_u16(out_fname: &str, data: Vec<u16>) -> io::Result<()> {
    let mut file = fs::File::create(out_fname)?;

    let mut writer = npyz::WriteOptions::new()
        .dtype(npyz::DType::Plain("<u2".parse::<TypeStr>().unwrap()))
        .writer(&mut file)
        .begin_1d()?;

    writer.extend(data)?;
    writer.finish()?;

    Ok(())
}

